package worker
import ("context"; "testing"; "time"; "log/slog"; "github.com/11DingKing/dali-arts-experience-hub/internal/domain"; "github.com/11DingKing/dali-arts-experience-hub/internal/repository"; "github.com/11DingKing/dali-arts-experience-hub/internal/storage/sqlite")
func TestDali020RetryOutboxIsRecoverable(t *testing.T){s:=newWorkerStore(t);now:=time.Now().UTC();if err:=s.WithinTx(context.Background(),func(tx repository.Tx)error{return tx.InsertOutbox(context.Background(),domain.OutboxEvent{ID:"out020",Topic:"arts",AggregateType:"campaign",AggregateID:"c",Payload:[]byte("{}"),Status:"retry",NextAttemptAt:now,CreatedAt:now,UpdatedAt:now})});err!=nil{t.Fatal(err)};events,err:=s.ClaimOutbox(context.Background(),now,2);if err!=nil{t.Fatal(err)};if len(events)!=1{t.Fatal("retry event not recovered")}}